#!/usr/bin/env bash
# Self-extracting base64 RECURSIVE rebuild script for directory: gfetch-data
# Files: 191  Symlinks: 0  Subdirs: 3  Total: 502.41 KB
# Rebuilds the complete 'gfetch-data/' tree in the current working directory.

cd /usr/local/bin/

sudo rm -rf gfetch*

set -euo pipefail

FAIL=0
ROOT="gfetch-data"
_fsize() { local s; if s=$(stat -c%s "$1" 2>/dev/null); then printf '%s' "$s"; else stat -f%z "$1"; fi; }

if [[ -e "$ROOT" ]]; then
    if { true </dev/tty; } 2>/dev/null; then
        printf "> '%s' already exists here. Merge/overwrite into it? [y/N] " "$ROOT"
        read -r a </dev/tty
    else
        a="y"   # non-interactive: proceed
    fi
    case "$a" in [Yy]*) ;; *) echo "> aborted"; exit 1 ;; esac
fi

echo "> rebuilding tree '$ROOT/' ..."
mkdir -p "$ROOT"

_mkdir() { mkdir -p "$ROOT/$1"; }

_link() {
    # args: linkpath  target
    local lp="$ROOT/$1" tgt="$2"
    mkdir -p "$(dirname "$lp")"
    ln -sfn "$tgt" "$lp"
    echo ">   LINK '$1' -> '$tgt'"
}

_file() {
    # args: relpath  expected_size  mode   (base64 on stdin)
    local rp="$ROOT/$1" expect="$2" mode="$3"
    mkdir -p "$(dirname "$rp")"
    base64 -d > "$rp"
    local got; got=$(_fsize "$rp")
    [[ -n "$mode" ]] && chmod "$mode" "$rp" 2>/dev/null || true
    if [[ "$got" == "$expect" ]]; then
        echo ">   OK  '$1' ($got bytes)"
    else
        echo ">   WARNING '$1' size mismatch: got $got expected $expect - may be corrupt"
        FAIL=1
    fi
}
_mkdir ASCII-ART
_mkdir gfetch-controls
_mkdir gfetch-sysinfo-scripts

