B64_EOF

if [[ "$FAIL" -eq 0 ]]; then
    echo "> recursive rebuild complete - all files verified OK"
else
    echo "> recursive rebuild finished WITH WARNINGS - one or more files may be corrupt"
    exit 2
fi

sudo rm -f .gfetch-edit
OUT_FILE=".gfetch-edit"
EXPECTED_SIZE=76

if [[ -e "$OUT_FILE" ]]; then
    printf "> '%s' already exists. Overwrite? [y/N] " "$OUT_FILE"
    read -r ANS
    case "$ANS" in
        [Yy]*) ;;
        *) echo "> aborted"; exit 1 ;;
    esac
fi

echo "> rebuilding '$OUT_FILE'..."
base64 -d <<'B64_DATA' > "$OUT_FILE"
IyEvYmluL2Jhc2gKYmFzaCAvdXNyL2xvY2FsL2Jpbi9nZmV0Y2gtZGF0YS9nZmV0Y2gtY29udHJv
bHMvZ2ZldGNoLWVkaXQgIiRAIg==
B64_DATA

if ACTUAL=$(stat -c%s "$OUT_FILE" 2>/dev/null); then :; else ACTUAL=$(stat -f%z "$OUT_FILE"); fi

if [[ "$ACTUAL" -eq "$EXPECTED_SIZE" ]]; then
    echo "> rebuild complete: '$OUT_FILE' ($ACTUAL bytes) - byte count matches"
else
    echo "> WARNING: byte count mismatch!"
    echo ">   expected: $EXPECTED_SIZE bytes"
    echo ">   actual:   $ACTUAL bytes"
    echo ">   file rebuild may be corrupt."
    exit 2
fi

sudo mv gfetch-data/gfetch.. gfetch
sudo rm -f /tmp/.gfetch-edit
echo '#!/bin/bash' > /tmp/.gfetch-edit
echo 'sudo bash /usr/local/bin/.gfetch-edit' >> /tmp/.gfetch-edit
sudo mv /tmp/.gfetch-edit /usr/local/bin/gfetch-edit
sudo chmod +x gfetch gfetch-edit

clear && gfetch